import { useEffect, useState } from "react";
import api from "../api";

function Feed() {
  /* ================= STATE ================= */
  const [posts, setPosts] = useState([]);
  const [filter, setFilter] = useState("ALL");

  const [activePost, setActivePost] = useState(null);
  const [comments, setComments] = useState([]);
  const [commentText, setCommentText] = useState("");
  const [showCreatePost, setShowCreatePost] = useState(false);


  // TEMP (later from login)
  const userRole = "ALUMNI";
  const userId = 1;

  /* ================= FETCH FEED ================= */
  useEffect(() => {
    fetchFeed();
  }, []);

  const fetchFeed = async () => {
    const res = await api.get("/feed");
    setPosts(res.data);
  };

  /* ================= LIKE ================= */
  const likePost = async (postId) => {
    await api.post("/post/like", {
      post_id: postId,
      user_id: userId,
    });
  };

  /* ================= COMMENTS ================= */
  const toggleComments = async (postId) => {
    if (activePost === postId) {
      setActivePost(null);
      return;
    }

    const res = await api.get(`/post/${postId}/comments`);
    setComments(res.data);
    setActivePost(postId);
  };

  const addComment = async () => {
    if (!commentText) return;

    await api.post("/post/comment", {
      post_id: activePost,
      user_id: userId,
      comment_text: commentText,
    });

    setCommentText("");
    toggleComments(activePost);
  };

  /* ================= FILTER ================= */
  const filteredPosts = posts.filter((post) => {
    if (filter === "ALL") return true;
    if (filter === "IMAGE") return post.image_url;
    if (filter === "ARTICLE") return !post.image_url;
    return true;
  });

  return (
    <div className="feed-page">
      {/* ========== LEFT SIDEBAR ========== */}
      <aside className="feed-sidebar">
        {userRole === "ALUMNI" && (
        <button className="sidebar-btn" onClick={() => setShowCreatePost(!showCreatePost)}>
            Create Post </button>
        )}
        <button className="sidebar-btn" onClick={() => setFilter("ALL")}>
          All 
        </button>

        <button className="sidebar-btn" onClick={() => setFilter("IMAGE")}>
          Posts
        </button>

        <button className="sidebar-btn" onClick={() => setFilter("ARTICLE")}>
          Article
        </button>
      </aside>

      {/* ========== MAIN FEED ========== */}
      <main className="feed-main">
        
        {filteredPosts.map((post) => (
          <div key={post.post_id} className="feed-card">
            <p className="post-content">{post.content}</p>

            {post.image_url && (
              <img
                src={`http://localhost:5000${post.image_url}`}
                alt="post"
                className="post-image"
              />
            )}
{showCreatePost && userRole === "ALUMNI" && (
  <div className="feed-card">
    <h4>Create Post</h4>

    <select
      value={postType}
      onChange={(e) => setPostType(e.target.value)}
    >
      <option value="ARTICLE">Article</option>
      <option value="IMAGE">Image</option>
    </select>

    <textarea
      placeholder="Write something..."
      value={content}
      onChange={(e) => setContent(e.target.value)}
    />

    {postType === "IMAGE" && (
      <input
        type="file"
        accept="image/*"
        onChange={(e) => setImageFile(e.target.files[0])}
      />
    )}

    <button onClick={handleCreatePost}>Post</button>
  </div>
)}

            {/* Like + Comment */}
            <div className="post-actions">
              <span onClick={() => likePost(post.post_id)}>❤️</span>
              <span onClick={() => toggleComments(post.post_id)}>💬</span>
            </div>

            {/* Comments */}
            {activePost === post.post_id && (
              <div className="comment-box">
                {comments.map((c, i) => (
                  <p key={i}>
                    <strong>{c.email}</strong>: {c.comment_text}
                  </p>
                ))}

                <input
                  placeholder="Write a comment..."
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                />
                <button onClick={addComment}>Post</button>
              </div>
            )}
          </div>
        ))}
      </main>
    </div>
  );
}

export default Feed;
